@push('scripts')<script>
(function(){const money=n=>'Q '+(n/100).toLocaleString('es-GT',{minimumFractionDigits:2,maximumFractionDigits:2});function calc(){let total=0;document.querySelectorAll('.aa-denom').forEach(el=>{const n=Math.max(0,Math.trunc(Number(el.value)||0))*Number(el.dataset.cents);total+=n;el.closest('tr').querySelector('.aa-sub').textContent=money(n)});const corte=Math.round((Number(document.getElementById('aa-corte').value)||0)*100);document.getElementById('aa-total').textContent=money(total);document.getElementById('aa-diff').textContent=(total<corte?'-':'')+money(Math.abs(total-corte));document.getElementById('aa-just').required=total!==corte}document.querySelectorAll('.aa-denom,#aa-corte').forEach(e=>e.addEventListener('input',calc));calc();document.getElementById('aa-form').addEventListener('submit',e=>{if(!confirm('¿Confirma el registro y firma electrónica del arqueo de auditoría?')){e.preventDefault();return}document.getElementById('aa-submit').disabled=true})})();
</script>@endpush
